select * from customer_behavior_clean;

-- Q1 What is the total revenue generated by male Vs female customer 
select gender, SUM(purchase_amount) as total_revenue 
from customer_behavior_clean
group by gender;

--Q2 Which customer used discount but still spent more than average purchase amount
select customer_id, purchase_amount
from customer_behavior_clean 
where discount_applied = 'Yes'
AND purchase_amount >= (Select AVG(purchase_amount)from customer_behavior_clean);

--Q3 Which are the TOP 5 products has hieghest average review rating.

select Top 5 item_purchased, Round(avg(review_rating),2) as avg_rating
from customer_behavior_clean
group by item_purchased 
having avg(review_rating) > (select avg(review_rating) from customer_behavior_clean)
order by avg(review_rating) desc;

--Q4 Compare the average shippibng amount between standard and express amount.
Select shipping_type, Avg(purchase_amount) as avg_puchase_amount
from customer_behavior_clean
where shipping_type in ('standard', 'Express')
group by shipping_type;

-- Q5 Do subscribed customer spend more ?  cpmapre avg spend and total revenue
-- between subscribers and non-subscribers ?

Select subscription_status,
Count(customer_id) as total_customer,
Round(sum(purchase_amount),2) total_revenue,
Round(Avg(purchase_amount),2) avg_spend
from customer_behavior_clean
group by subscription_status;  

