--Q6 Which 5 products have highest percentage of purchases with discounts applied?

Select top 5 item_purchased,
 Round(100 * SUM(Case when discount_applied = 'Yes' then 1 else 0 end) / count(*),2) as discount_rate
from customer_behavior_clean
group by item_purchased
order by discount_rate desc;


--Q7 Segment customer into new , returning and loyal based on their total number of previous purchases
-- show the count of each segment

With customer_type as (
Select customer_id, previous_purchases,
	case
		when previous_purchases = 1 then 'New'
		when previous_purchases  between 2 and 10 then 'Returning'
		else 'Loyal'
		End as customer_segment
from customer_behavior_clean
)

select customer_segment, count(*) as 'Number of customer'
from customer_type
group by customer_segment
order by [Number of customer]desc;

--Q8 WHat are the TOP 3 most purchased products within each category ?
-- TOP 3 products 
--within each category

with item_count as (
select  category, 
item_purchased,
count(customer_id) as total_orders,
Dense_RANK() over( partition by category order by purchase_amount desc) as item_rank
from customer_behavior_clean
group by category, item_purchased
)
select item_rank,category,item_purchased, total_orders
from item_count
where item_rank<=3;

--Q9 As customers who repeat buyers (more than 5 previous purachase) are likely to subcribes

select subscription_status,
count(customer_id) as total_customer
from customer_behavior_clean
where previous_purchases> 5
group by subscription_status;

--Q10 What is the revenue contribution of each age group ?

select age_group, sum(purchase_amount) as total_revenue
from customer_behavior_clean
group by age_group
order by total_revenue desc;





